export function windowBox(g, x0, x1, y, z, opts = {}) {
  const out = [], a = Math.min(x0, x1), b = Math.max(x0, x1);
  for (let x = a; x <= b; x++) {
    put(g, out, opts, x, y, z, "dark_oak_slab", { type: "top" });
    put(g, out, opts, x, y + 1, z, (x - a) % 2 === 0 ? "potted_poppy" : "potted_dandelion");
